def fill_generation_defaults(generation_config):
    for k, v in _TF4_GENERATION_DEFAULTS.items():
        if getattr(generation_config, k, None) is None:
            setattr(generation_config, k, v)
    return generation_config


# from removed transformers.utils.model_parallel_utils / cache_utils names

try:
    from transformers.utils.model_parallel_utils import assert_device_map, get_device_map
except ImportError:
    def assert_device_map(device_map, num_blocks):
        blocks = list(range(0, num_blocks))
        seen, duplicate_blocks = [], []
        for layers in device_map.values():
            for j in layers:
                if j in seen:
                    duplicate_blocks.append(j)
                seen.append(j)
        missing_blocks = [i for i in blocks if i not in seen]
        extra_blocks = [i for i in seen if i not in blocks]
        if duplicate_blocks:
            raise ValueError(f"Duplicate attention blocks specified in device_map: {duplicate_blocks}")
        if missing_blocks:
            raise ValueError(f"Attention blocks missing from device_map: {missing_blocks}")
        if extra_blocks:
            raise ValueError(f"device_map contains more attention blocks than the model has: {extra_blocks}")

    def get_device_map(n_layers, devices):
        devices = list(devices)
        layers = list(range(n_layers))
        n_blocks = int(ceil(n_layers / len(devices)))
        layers_list = [layers[i:i + n_blocks] for i in range(0, n_layers, n_blocks)]
        return dict(zip(devices, layers_list))

